package com.musicplaylist.controller;
import com.musicplaylist.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/playlists/remove-song") public class RemoveFromPlaylistServlet extends HttpServlet {protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{Integer uid=Auth.userId(q);if(uid==null){p.sendRedirect(q.getContextPath()+"/login");return;}try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("DELETE ps FROM playlist_songs ps JOIN playlists pl ON pl.id=ps.playlist_id WHERE ps.playlist_id=? AND ps.song_id=? AND pl.user_id=?")){int pl=Integer.parseInt(q.getParameter("playlistId"));s.setInt(1,pl);s.setInt(2,Integer.parseInt(q.getParameter("songId")));s.setInt(3,uid);s.executeUpdate();p.sendRedirect(q.getContextPath()+"/playlist?id="+pl);}catch(SQLException|NumberFormatException x){throw new ServletException(x);}}}